import { chat } from "../diligence/llm";
import type { Deal } from "../diligence/types";
import type { CompanyProfile } from "./types";

type DeckExtract = {
  founders?: string[] | null;
  sector?: string | null;
  product?: string | null;
  geography?: string | null;
  stage?: string | null;
  fundraise?: string | null;
  businessModel?: string | null;
};

function blank(value?: string | null): boolean {
  if (!value) return true;
  return /^(unknown|n\/?a|none|tbd)(\b|$)/i.test(value.trim()) || /inbound room/i.test(value);
}

function deckText(deal: Deal): string {
  const decks = deal.docs.filter((doc) => doc.role === "deck" || doc.kind === "deck");
  const src = decks.length ? decks : deal.docs;
  return src
    .map((doc) => doc.markdown)
    .join("\n\n")
    .replace(/<!--.*?-->/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 14000);
}

function parseExtract(raw: string): DeckExtract | null {
  const start = raw.indexOf("{");
  const end = raw.lastIndexOf("}");
  if (start < 0 || end <= start) return null;
  try {
    return JSON.parse(raw.slice(start, end + 1)) as DeckExtract;
  } catch {
    return null;
  }
}

function cleanNames(values?: string[] | null): string[] {
  if (!values) return [];
  const seen = new Set<string>();
  const out: string[] = [];
  for (const raw of values) {
    const name = raw.replace(/\s+/g, " ").replace(/^dr\.?\s+/i, "Dr. ").trim();
    const key = name.toLowerCase();
    if (!name || name.length < 4 || name.length > 60) continue;
    if (/\d|@|http/i.test(name)) continue;
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(name);
  }
  return out.slice(0, 4);
}

export function hasNamedFounders(profile: CompanyProfile): boolean {
  return profile.founders.some((name) => name.trim().length > 2);
}

export function hasMarketSignal(deal: Deal, profile: CompanyProfile): boolean {
  if (!blank(profile.sector) && !/inbound room/i.test(profile.sector)) return true;
  if (!blank(profile.product) && profile.product.trim().toLowerCase() !== profile.company.trim().toLowerCase()) {
    return true;
  }
  return deal.flags.some((flag) => flag.metric === "tam") || deal.metrics.some((metric) => metric.name === "tam");
}

export async function fillProfileFromDeck(deal: Deal, profile: CompanyProfile): Promise<CompanyProfile> {
  const text = deckText(deal);
  if (text.length < 80) return profile;

  const raw = await chat(
    [
      {
        role: "system",
        content:
          "Extract only facts written in the inbound deck. Do not invent people, sectors, cities, or raise terms. If a field is not stated, return null. Founders means people named as founder, co-founder, CEO/CTO who founded — not VP, head of, or advisors. Return JSON only.",
      },
      {
        role: "user",
        content: `Company on the folder: ${profile.company}\n\nDeck:\n${text}\n\nJSON shape:\n{"founders":["Full Name"]|null,"sector":"short sector"|null,"product":"what they sell"|null,"geography":"city or country"|null,"stage":"Pre-seed|Seed|Series A|Series B"|null,"fundraise":"raise line"|null,"businessModel":"how they charge"|null}`,
      },
    ],
    { maxTokens: 400 },
  );
  const extracted = parseExtract(raw);
  if (!extracted) return profile;

  const founders = cleanNames(extracted.founders);
  const pick = (value?: string | null, fallback = "") => {
    const next = value?.replace(/\s+/g, " ").trim() ?? "";
    return blank(next) ? fallback : next.slice(0, 160);
  };

  return {
    ...profile,
    founders: founders.length ? founders : profile.founders,
    sector: pick(extracted.sector, profile.sector),
    product: pick(extracted.product, profile.product),
    geography: pick(extracted.geography, profile.geography),
    stage: pick(extracted.stage, profile.stage),
    fundraise: pick(extracted.fundraise, profile.fundraise),
    businessModel: pick(extracted.businessModel, profile.businessModel),
  };
}

import { fillProfileFromDeck, hasMarketSignal, hasNamedFounders } from "../intelligence/fromDeck";
import type { Deal } from "./types";
import { firecrawlReady } from "./firecrawl";
import { researchFounders, researchMarket } from "./research";
import { saveDeal } from "./store";

function stamp(deal: Deal, title: string, body: string) {
  const intel = deal.intelligence;
  if (!intel) return;
  intel.timeline.push({
    id: `tl-${deal.id}-src-${Date.now()}`,
    at: new Date().toISOString(),
    title,
    body,
    source: "Source diligence",
  });
}

export async function ensureSourceResearch(deal: Deal): Promise<Deal> {
  if (!deal.intelligence) return deal;
  if (deal.intelligence.research?.founders?.length || deal.intelligence.research?.market?.summary) {
    return deal;
  }

  deal.intelligence.profile = await fillProfileFromDeck(deal, deal.intelligence.profile);
  const profile = deal.intelligence.profile;
  const foundersOk = hasNamedFounders(profile);
  const marketOk = hasMarketSignal(deal, profile);

  deal.intelligence.research = { ...deal.intelligence.research };
  await saveDeal(deal);

  if (!foundersOk && !marketOk) {
    stamp(deal, "Source diligence", "Deck named no founders and no market hook. We did not search the open web.");
    await saveDeal(deal);
    return deal;
  }

  if (!firecrawlReady()) {
    stamp(deal, "Source diligence", "Deck facts are on the profile. Public founder and market reads need FIRECRAWL_API_KEY.");
    await saveDeal(deal);
    return deal;
  }

  if (foundersOk) {
    try {
      const founders = await researchFounders(deal);
      deal.intelligence.research = { ...deal.intelligence.research, founders };
      stamp(
        deal,
        "Founder reads",
        `Public history on ${founders.map((person) => person.name).join(", ") || "named founders"}.`,
      );
      await saveDeal(deal);
    } catch (error) {
      stamp(deal, "Founder reads", `Skipped: ${(error as Error).message}`);
      await saveDeal(deal);
    }
  } else {
    stamp(deal, "Founder reads", "No founders named on the deck. We did not search the company name.");
    await saveDeal(deal);
  }

  if (marketOk) {
    try {
      const market = await researchMarket(deal);
      deal.intelligence.research = { ...deal.intelligence.research, market };
      stamp(deal, "Market read", market.summary || "Public market sources landed.");
      await saveDeal(deal);
    } catch (error) {
      stamp(deal, "Market read", `Skipped: ${(error as Error).message}`);
      await saveDeal(deal);
    }
  } else {
    stamp(deal, "Market read", "No sector, product, or TAM on the deck. We did not invent a market.");
    await saveDeal(deal);
  }

  return deal;
}

